tool_input.command:
node --input-type=module -e "
import { handle } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const { body: r } = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'x', at: '2026-03-01T09:00', tzOffsetMin: 330 } });
console.log('due_ms (UTC):', new Date(r.due_ms).toISOString());
for (const iso of ['2026-02-28T22:00:00Z', '2026-03-01T03:30:00Z']) console.log('now', iso, 'due?', dueReminders([r], Date.parse(iso)).length === 1);
" && node --test test/ 2>&1 | tail -8
